CREATE TABLE IF NOT EXISTS users (id VARCHAR(40) PRIMARY KEY, email VARCHAR(180) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password TEXT NOT NULL, role VARCHAR(20) NOT NULL, field VARCHAR(20) NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(40) NOT NULL, csrf VARCHAR(64) NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS programs (id VARCHAR(40) PRIMARY KEY, name VARCHAR(180) NOT NULL, field VARCHAR(20) NOT NULL, kind VARCHAR(20) NOT NULL, description TEXT NOT NULL, requirements TEXT NOT NULL, is_open INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS applications (id VARCHAR(40) PRIMARY KEY, owner_id VARCHAR(40) NOT NULL, program_id VARCHAR(40) NOT NULL, field VARCHAR(20) NOT NULL, kind VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, details TEXT NOT NULL, created BIGINT NOT NULL, updated BIGINT NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS files (id VARCHAR(40) PRIMARY KEY, application_id VARCHAR(40) NOT NULL, requirement VARCHAR(120) NOT NULL, name VARCHAR(180) NOT NULL, mime VARCHAR(80) NOT NULL, bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audits (id VARCHAR(40) PRIMARY KEY, application_id VARCHAR(40) NOT NULL, actor VARCHAR(40) NOT NULL, action VARCHAR(40) NOT NULL, note TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS contents (id VARCHAR(40) PRIMARY KEY, category VARCHAR(30) NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, year INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS public_files (id VARCHAR(40) PRIMARY KEY, name VARCHAR(180) NOT NULL, mime VARCHAR(80) NOT NULL, bytes INTEGER NOT NULL, kind VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id VARCHAR(40) PRIMARY KEY, photo_id VARCHAR(40) NOT NULL, name VARCHAR(180) NOT NULL, nip VARCHAR(18) NOT NULL UNIQUE, position VARCHAR(180) NOT NULL, employment_type VARCHAR(10) NOT NULL, placement VARCHAR(30) NOT NULL, published BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS activities (id VARCHAR(40) PRIMARY KEY, photo_id VARCHAR(40) NOT NULL, name VARCHAR(180) NOT NULL, description TEXT NOT NULL, activity_date VARCHAR(10) NOT NULL, field VARCHAR(30) NOT NULL, published BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS public_documents (id VARCHAR(40) PRIMARY KEY, file_id VARCHAR(40) NOT NULL, name VARCHAR(180) NOT NULL, year INTEGER NOT NULL, publish_date VARCHAR(10) NOT NULL, published BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS announcements (id VARCHAR(40) PRIMARY KEY, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, publish_date VARCHAR(10) NOT NULL, expires_date VARCHAR(10), field VARCHAR(30) NOT NULL, important INTEGER NOT NULL DEFAULT 0, published BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_media (activity_id VARCHAR(40) NOT NULL, file_id VARCHAR(40) NOT NULL, position INTEGER NOT NULL, PRIMARY KEY (activity_id,file_id));
CREATE TABLE IF NOT EXISTS activity_videos (activity_id VARCHAR(40) PRIMARY KEY, youtube_id VARCHAR(11) NOT NULL);
CREATE TABLE IF NOT EXISTS field_contacts (field VARCHAR(20) PRIMARY KEY, contact_name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(180) NOT NULL, schedule TEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS information_requests (id VARCHAR(40) PRIMARY KEY, owner_id VARCHAR(40) NOT NULL, subject VARCHAR(180) NOT NULL, details TEXT NOT NULL, purpose TEXT NOT NULL, phone VARCHAR(30) NOT NULL, field VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, created BIGINT NOT NULL, updated BIGINT NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS information_replies (id VARCHAR(40) PRIMARY KEY, request_id VARCHAR(40) NOT NULL, actor_id VARCHAR(40) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL, file_id VARCHAR(40) NOT NULL, file_name VARCHAR(180) NOT NULL, created BIGINT NOT NULL, is_public INTEGER NOT NULL DEFAULT 1);
